533	func TestCorruptAndVersion(t *testing.T) {
534		path := filepath.Join(t.TempDir(), "map.pose")
535		m, err := Create(path, baseConfig())
536		if err != nil {
537			t.Fatal(err)
538		}
539		if err := m.Close(); err != nil {
540			t.Fatal(err)
541		}
542		good, err := os.ReadFile(path)
543		if err != nil {
544			t.Fatal(err)
545		}
546	
547		writeBytes := func(name string, data []byte) string {
548			p := filepath.Join(t.TempDir(), name)
549			if err := os.WriteFile(p, data, 0o644); err != nil {
550				t.Fatal(err)
551			}
552			return p
553		}
554	
555		if _, err := Open(writeBytes("short", good[:5])); !errors.Is(err, ErrCorrupt) {
556			t.Fatalf("truncated: %v", err)
557		}
558		badMagic := append([]byte(nil), good...)
559		copy(badMagic[:8], "XXXXXXXX")
560		if _, err := Open(writeBytes("magic", badMagic)); !errors.Is(err, ErrCorrupt) {
561			t.Fatalf("bad magic: %v", err)
562		}
563		// 翻转 payload 中一个字节，CRC 不匹配。
564		flip := append([]byte(nil), good...)
565		flip[headerLen+1] ^= 0xFF
566		if _, err := Open(writeBytes("flip", flip)); !errors.Is(err, ErrCorrupt) {
567			t.Fatalf("checksum: %v", err)
568		}
569		// 长度字段被改。
570		badLen := append([]byte(nil), good...)
571		badLen[10] ^= 0x01
572		if _, err := Open(writeBytes("len", badLen)); !errors.Is(err, ErrCorrupt) {
573			t.Fatalf("length: %v", err)
574		}
575	
576		// 支持的版本可以打开；构造一个 CRC 合法但版本号不受支持的文件。
577		raw := append([]byte(nil), good...)
578		raw[8] = 0x00
579		raw[9] = 0x02 // version 2
580		// 重算 CRC。
581		sum := crc32.ChecksumIEEE(raw[:len(raw)-4])
582		binary.BigEndian.PutUint32(raw[len(raw)-4:], sum)
583		if _, err := Open(writeBytes("ver", raw)); !errors.Is(err, ErrUnsupportedVersion) {
584			t.Fatalf("unsupported version: %v", err)
585		}
586	
587		// 损坏文件不应被 Open/Create 静默当作新地图：Create 对已存在损坏文件同样拒绝。
588		corruptPath := writeBytes("corrupt.pose", flip)
589		if _, err := Open(corruptPath); !errors.Is(err, ErrCorrupt) {
590			t.Fatal(err)
591		}
592		if _, err := Create(corruptPath, baseConfig()); err == nil {
593			t.Fatal("Create overwrote corrupt file")
594		}
595	}
