480			_, err = m2.Correct(Correction{ID: "c", Anchor: anchor, Target: CorrectionTarget{X: 1}})
481			r, ok := AsRejectError(err)
482			if !ok || r.Kind != RejectNoBasis {
483				t.Fatalf("anchor %d: err = %v, want no_basis", anchor, err)
484			}
485		}
486	
487		// 旧地图上可继续导入：t=300 位姿 (2.5,0)，K 观测 (2.5,0) 距旧均值
488		// (1.5,0) 恰为合并距离，接受；K 均值变为 5.5/3，次数 3。
489		if _, err := m2.ImportSegment(Segment{ID: "new", Frames: []Frame{
490			{Time: 300, DX: 0.5, Observations: []Observation{{ID: "K"}}},
491		}}); err != nil {
492			t.Fatalf("append to legacy: %v", err)
493		}
494		lms, _ = m2.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
495		if len(lms) != 1 || lms[0].Count != 3 {
496			t.Fatalf("K after append = %v", lms)
497		}
498		approxEq(t, "K mean after append", lms[0].X, 5.5/3.0)
499	
500		// 仅覆盖依据完整新范围的校正可成功；旧观测贡献固定不变。
501		rec, err := m2.Correct(Correction{ID: "c2", Anchor: 300, Target: CorrectionTarget{X: 2.0, Y: 0}})
502		if err != nil {
503			t.Fatalf("correct new range: %v", err)
504		}
505		if rec.EndTime != 300 || len(rec.Poses) != 1 {
506			t.Fatalf("record = %+v", rec)
507		}
508		// 新观测从 (2.5,0) 移到 (2.0,0)，与固定旧均值 (1.5,0) 距离 0.5 可接受。
509		lc := rec.Landmarks[0]
510		if lc.ID != "K" {
511			t.Fatalf("change id = %q", lc.ID)
512		}
513		approxEq(t, "K after correct", lc.After.X, (1.5*2+2.0)/3.0)
514		if lc.After.Count != 3 {
515			t.Fatalf("K count = %d", lc.After.Count)
516		}
517	
518		// 新范围校正若让新观测远离固定旧贡献，仍冲突拒绝。
519		_, err = m2.Correct(Correction{ID: "c3", Anchor: 300, Target: CorrectionTarget{X: 10, Y: 0}})
520		r, ok := AsRejectError(err)
521		if !ok || r.Kind != RejectLandmarkConflict || r.Landmark != "K" || r.Time != 300 {
522			t.Fatalf("legacy conflict err = %v", err)
523		}
524	
525		// 重开后：null 来源（旧帧）与校正记录都保持。
526		if err := m2.Close(); err != nil {
527			t.Fatal(err)
528		}
529		m3, err := Open(path)
530		if err != nil {
531			t.Fatal(err)
532		}
533		defer m3.Close()
534		if _, err := m3.Correct(Correction{ID: "x", Anchor: 100, Target: CorrectionTarget{X: 1}}); err == nil {
535			t.Fatal("old range became correctable after reopen")
536		}
537		recs, _ := m3.Corrections()
538		if len(recs) != 1 || recs[0].ID != "c2" {
539			t.Fatalf("records after legacy reopen = %v", recs)
540		}
541	}
542	
543	func TestCorrectionSaveFailureRollback(t *testing.T) {
544		dir := t.TempDir()
545		path := filepath.Join(dir, "map.pose")
546		m, err := Create(path, baseConfig())
