	}
}

func TestInvalidateSetOrderIndependent(t *testing.T) {
	m := seedOccurrenceMap(t)
	req := Invalidation{ID: "op", Reason: "r", Landmarks: []string{"M", "L"}}
	first, err := m.Invalidate(req)
	if err != nil {
		t.Fatal(err)
